import random
import string

# Load valid words
with open('/workdir/data/dict.txt', 'r') as f:
    words_set = set()
    for line in f:
        w = line.strip().lower()
        if w and all(c in 'abcdefghijklmnopqrstuvwxyz' for c in w):
            words_set.add(w)

print(f"Total words: {len(words_set)}")

def random_derangement():
    letters = list(string.ascii_lowercase)
    perm = letters[:]
    while True:
        random.shuffle(perm)
        if not any(perm[i] == letters[i] for i in range(26)):
            break
    mapping = {letters[i]: perm[i] for i in range(26)}
    return mapping

def count_matching_words(mapping):
    count = 0
    matching = []
    for w in words_set:
        if len(w) < 4:
            continue
        transformed = ''.join(mapping[c] for c in w)
        if transformed in words_set:
            count += 1
            matching.append((w, transformed))
    return count, matching

# Keep trying until we find a good one with good character coverage
best_mapping = None
best_words = None
best_count = 0
best_unique_chars = 0

for trial in range(5000):
    mapping = random_derangement()
    count, matching = count_matching_words(mapping)
    if count >= 50:
        # Check unique characters in the matching words
        unique_chars = set()
        for w, _ in matching:
            unique_chars.update(w)
        if len(unique_chars) >= 24:
            print(f"Trial {trial}: {count} words, {len(unique_chars)} unique chars")
            if len(unique_chars) > best_unique_chars:
                best_unique_chars = len(unique_chars)
                best_mapping = mapping
                best_words = matching
                print(f"  New best: {best_unique_chars} unique chars")
                if best_unique_chars >= 24:
                    print("  SUCCESS: Found solution!")
                    break

if best_mapping is None:
    print("No solution found in 5000 trials")
else:
    print(f"\nFinal result: {len(best_words)} words, {best_unique_chars} unique chars")
    print(f"Mapping: {best_mapping}")
    print(f"\nFirst 20 words: {best_words[:20]}")
